function cleanPath(path: string): string {
  const stack: string[] = [];
  let i = 0;
  while (i < path.length) {
    while (i < path.length && path[i] === "/") i++;
    const from = i;
    while (i < path.length && path[i] !== "/") i++;
    const part = path.slice(from, i);
    if (part === "" || part === ".") continue;
    if (part === "..") stack.pop();
    else stack.push(part);
  }
  return "/" + stack.join("/");
}

